SCHEMA = [
    ("DATABASE_URL", True, False, None),
    ("LOG_LEVEL", False, False, "info"),
    ("STRIPE_KEY", True, True, None),
]

STAGING_ENV = {
    "DATABASE_URL": "postgres://app@staging-db/app",
    "STRIPE_KEY": "sk_test_51Hx",
}

PROD_ENV = {
    "DATABASE_URL": "postgres://app@prod-db/app",
    "LOG_LEVEL": "warn",
}

def boot_config(env_name, environ):
    print(f"== boot: {env_name} ==")
    resolved = 0
    for name, required, is_secret, default in SCHEMA:
        if name in environ:
            value, source = environ[name], "env"
        elif default is not None:
            value, source = default, "default"
        elif required:
            kind = "secret" if is_secret else "key"
            print(f"FATAL: missing required {kind} {name}")
            print("boot: EXIT 1")
            return
        else:
            continue
        shown = "***redacted***" if is_secret else value
        print(f"{name}={shown} ({source})")
        resolved += 1
    print(f"boot: OK ({resolved} keys resolved)")

boot_config("staging", STAGING_ENV)
boot_config("prod", PROD_ENV)

