STACK = {
    "db": [],
    "redis": [],
    "migrate": ["db"],
    "api": ["migrate", "redis"],
    "worker": ["api", "redis"],
}

BROKEN = {
    "db": [],
    "api": ["db", "vault"],
    "worker": ["scheduler"],
    "scheduler": ["worker"],
}

def boot_waves(name, services):
    print(f"== compose up: {name} ==")
    for svc in services:
        for dep in services[svc]:
            if dep not in services:
                print(f"ERROR: {svc} depends on undefined service '{dep}'")
                return
    started = set()
    remaining = dict(services)
    wave = 0
    while remaining:
        ready = sorted(s for s, deps in remaining.items() if all(d in started for d in deps))
        if not ready:
            print(f"ERROR: dependency cycle among: {', '.join(sorted(remaining))}")
            return
        wave += 1
        print(f"wave {wave}: {', '.join(ready)}")
        for s in ready:
            started.add(s)
            del remaining[s]
    print(f"boot order: {len(started)} services, {wave} waves, 0 cycles")

boot_waves("stack", STACK)
boot_waves("broken", BROKEN)

