DNS = {"checkout.shop.dev": "203.0.113.40", "api.shop.dev": "203.0.113.40"}
LB_IP = "203.0.113.40"
CERT_SANS = ["shop.dev", "www.shop.dev", "checkout.shop.dev"]
INGRESS_HOSTS = {"checkout.shop.dev": "checkout-svc", "api.shop.dev": "api-svc"}
SERVICES = {"checkout-svc": {"app": "checkout"}, "api-svc": {"app": "orders-api"}}
PODS = [
    {"labels": {"app": "checkout"}, "ready": True},
    {"labels": {"app": "checkout"}, "ready": True},
    {"labels": {"app": "orders"}, "ready": True},
]
HOSTS = ["checkout.shop.dev", "api.shop.dev"]

def san_covers(host, san):
    if san == host:
        return True
    if san.startswith("*."):
        zone = san[2:]
        return host.endswith("." + zone) and host.count(".") == zone.count(".") + 1
    return False

def check_path(hosts):
    first_break = None
    for host in hosts:
        hops = []
        if DNS.get(host) == LB_IP:
            hops.append("dns OK")
        else:
            hops.append("dns FAIL (no record pointing at the load balancer)")
            print(f"{host}: " + " -> ".join(hops))
            if first_break is None:
                first_break = ("dns", host)
            continue
        if any(san_covers(host, s) for s in CERT_SANS):
            hops.append("tls OK")
        else:
            hops.append(f"tls FAIL (SAN mismatch: cert covers {', '.join(CERT_SANS[:2])})")
            print(f"{host}: " + " -> ".join(hops))
            if first_break is None:
                first_break = ("tls", host)
            continue
        if host in INGRESS_HOSTS:
            hops.append("ingress OK")
        else:
            hops.append("ingress FAIL (no host rule)")
            print(f"{host}: " + " -> ".join(hops))
            if first_break is None:
                first_break = ("ingress", host)
            continue
        selector = SERVICES[INGRESS_HOSTS[host]]
        ready = sum(1 for p in PODS if p["ready"] and all(p["labels"].get(k) == v for k, v in selector.items()))
        if ready >= 1:
            hops.append(f"service OK ({ready} ready endpoints) -> HEALTHY")
            print(f"{host}: " + " -> ".join(hops))
        else:
            sel = ",".join(f"{k}={v}" for k, v in selector.items())
            hops.append(f"service FAIL (selector {sel} matches 0 ready pods)")
            print(f"{host}: " + " -> ".join(hops))
            if first_break is None:
                first_break = ("service", host)
    if first_break:
        print(f"first broken hop: {first_break[0]} ({first_break[1]})")
    else:
        print("first broken hop: none")

check_path(HOSTS)

health-readiness-liveness.code:
PODS = ["pod-a", "pod-b", "pod-c"]
TIMELINE = {
    3: {"pod-b": (False, True)},
    5: {"pod-b": (True, True)},
    6: {"pod-c": (False, False)},
    7: {"pod-c": (False, False)},
    8: {"pod-c": (False, False)},
}

def run_probe_loop(pods, timeline):
    state = {p: {"ready": True, "alive": True} for p in pods}
    endpoints = set(pods)
    fail_count = {p: 0 for p in pods}
    restart_due = {}
    drains = restarts = 0
    for t in range(1, 11):
        for p in pods:
            if p in restart_due:
                if restart_due[p] == t:
                    endpoints.add(p)
                    del restart_due[p]
                    state[p] = {"ready": True, "alive": True}
                    fail_count[p] = 0
                    print(f"t{t} {p} restarted -> back in endpoints")
                continue
            upd = timeline.get(t, {}).get(p)
            if upd:
                state[p] = {"ready": upd[0], "alive": upd[1]}
            ready, alive = state[p]["ready"], state[p]["alive"]
            if not ready and p in endpoints:
                endpoints.discard(p)
                drains += 1
                print(f"t{t} {p} readiness fail -> removed from endpoints")
            elif ready and p not in endpoints:
                endpoints.add(p)
                print(f"t{t} {p} readiness ok -> back in endpoints")
            if not alive:
                fail_count[p] += 1
                if fail_count[p] >= 3:
                    print(f"t{t} {p} liveness fail 3/3 -> RESTART")
                    restarts += 1
                    endpoints.discard(p)
                    restart_due[p] = t + 2
                    fail_count[p] = 0
                else:
                    print(f"t{t} {p} liveness fail {fail_count[p]}/3")
            else:
                fail_count[p] = 0
    print(f"endpoints at t10: {', '.join(sorted(endpoints))}")
    print(f"drains: {drains}, restarts: {restarts}")

run_probe_loop(PODS, TIMELINE)

