     "readinessProbe": True, "livenessProbe": True,
     "requests": {"cpu": "250m"}, "limits": {"cpu": "1"}, "maxUnavailablePct": 0},
    {"name": "payments", "replicas": 4, "image": "registry/payments:latest",
     "readinessProbe": False, "livenessProbe": True,
     "requests": {"cpu": "500m"}, "limits": {"cpu": "2"}, "maxUnavailablePct": 25},
    {"name": "worker", "replicas": 2, "image": "registry/worker@sha256:41c7aa09",
     "readinessProbe": True, "livenessProbe": True,
     "requests": None, "limits": None, "maxUnavailablePct": 50},
]

def lint_manifests(manifests):
    ship_ready = 0
    for m in manifests:
        violations = []
        if not m["readinessProbe"]:
            violations.append("no readinessProbe")
        if not m["livenessProbe"]:
            violations.append("no livenessProbe")
        if not m["requests"] or not m["limits"]:
            violations.append("no resource requests+limits")
        if m["maxUnavailablePct"] > 25:
            violations.append("maxUnavailable too high")
        if m["image"].endswith(":latest") or "@sha256:" not in m["image"]:
            violations.append("image not digest-pinned")
        if violations:
            print(f"{m['name']}: {len(violations)} violations ({'; '.join(violations)}) -> BLOCK")
        else:
            ship_ready += 1
            print(f"{m['name']}: 0 violations -> SHIP")
    print(f"fleet: {ship_ready}/{len(manifests)} manifests ship-ready")

lint_manifests(MANIFESTS)

