    "aws_instance.legacy-worker": {"instance_count": 1, "type": "t3.medium"},
}

def plan(desired, live):
    adds = changes = destroys = 0
    warnings = []
    for name in sorted(set(desired) | set(live)):
        if name in desired and name not in live:
            print(f"+ create {name}")
            adds += 1
        elif name in live and name not in desired:
            print(f"- destroy {name}")
            destroys += 1
        else:
            for attr in desired[name]:
                cv, lv = desired[name][attr], live[name][attr]
                if cv != lv:
                    print(f"~ update {name} {attr}: live={lv} code={cv} -> revert to {cv}")
                    changes += 1
                    if attr == "instance_count" and lv > cv:
                        warnings.append(f"warning: reverting live capacity {lv}->{cv} may re-trigger the incident; codify the fix first")
    print(f"plan: {adds} to add, {changes} to change, {destroys} to destroy")
    for w in warnings:
        print(w)

plan(DESIRED, LIVE)

