    ("4f2a", "s5", "s2", "inventory", "reserve_items", 240, False),
    ("9b31", "t1", None, "gateway", "GET /search", 95, False),
]

LOGS = [
    ("4f2a", "card-vault", "tls handshake to processor timed out"),
    ("4f2a", "checkout", "order create failed downstream"),
    ("9b31", "gateway", "cache hit"),
]

ALERT_TRACE = "4f2a"

def analyze_trace(trace_id):
    spans = {s[1]: s for s in SPANS if s[0] == trace_id}
    children = {}
    root = None
    for sid, s in spans.items():
        if s[2] is None:
            root = sid
        else:
            children.setdefault(s[2], []).append(sid)
    def error_free_children(sid):
        return all(not spans[c][6] for c in children.get(sid, []))
    cause = None
    for sid, s in spans.items():
        if s[6] and error_free_children(sid):
            cause = sid
    path = []
    cur = cause
    while cur is not None:
        path.append(cur)
        cur = spans[cur][2]
    path.reverse()
    parts = []
    for sid in path[:-1]:
        s = spans[sid]
        parts.append(f"{s[3]}({s[5]}ms)")
    last = spans[path[-1]]
    parts.append(f"{last[3]}(ERROR {last[5]}ms)")
    print(f"trace {trace_id}: " + " -> ".join(parts))
    print(f"root cause span: {last[3]} {last[4]} ({last[5]}ms, error)")
    for tid, svc, msg in LOGS:
        if tid == trace_id and svc == last[3]:
            print(f'log match: trace_id={tid} service={svc} msg="{msg}"')
            break
    print("pivots: metric -> trace -> log, one trace_id end to end")

analyze_trace(ALERT_TRACE)

alerting-slo-error-budgets.code:
SLO_ALLOWED = 0.001

SCENARIOS = [
    ("spike-then-gone", {"5m": 0.022, "1h": 0.0018, "6h": 0.0007, "3d": 0.0004}),
    ("deploy-fast-burn", {"5m": 0.009, "1h": 0.0091, "6h": 0.004, "3d": 0.0012}),
    ("slow-leak", {"5m": 0.0009, "1h": 0.0011, "6h": 0.0034, "3d": 0.0016}),
    ("healthy", {"5m": 0.0002, "1h": 0.0003, "6h": 0.0002, "3d": 0.0002}),
]

def evaluate_burn(scenarios):
    for name, rates in scenarios:
        b = {w: rates[w] / SLO_ALLOWED for w in rates}
        burns = f"5m={b['5m']:.1f}x 1h={b['1h']:.1f}x 6h={b['6h']:.1f}x 3d={b['3d']:.1f}x"
        if (b["5m"] >= 14.0 and b["1h"] >= 14.0) or (b["5m"] >= 8.0 and b["1h"] >= 8.0):
            hours = 720 / b["1h"]
            verdict = f"PAGE (sustained fast burn, budget gone in {hours:.1f}h)"
        elif b["6h"] >= 3.0 and b["3d"] >= 1.0:
            days = 30 / b["3d"]
            verdict = f"TICKET (slow leak, budget gone in {days:.1f}d)"
        elif b["5m"] >= 8.0:
            verdict = "NO ALERT (short blip, self-healed)"
        else:
            verdict = "NO ALERT (within budget)"
        print(f"{name}: {burns} -> {verdict}")
    print("budget: 43.2 min / 30d")

evaluate_burn(SCENARIOS)

