TRUSTED_SIGNERS = {"releases@corp"}

ARTIFACTS = [
    {"name": "orders:v2.4", "signed_by": "releases@corp", "sbom": True, "criticals": [], },
    {"name": "orders:v2.4-hotfix", "signed_by": None, "sbom": True, "criticals": []},
    {"name": "etl:v1.9", "signed_by": "releases@corp", "sbom": True,
     "criticals": ["CVE-2025-1123", "CVE-2025-4410"]},
    {"name": "orders:v2.4-retag", "signed_by": "dev-laptop@corp", "sbom": False, "criticals": []},
]

DEPS = {
    "app": ["express-mw", "pg-driver"],
    "express-mw": ["log-fmt"],
    "log-fmt": ["left-pad-ng"],
    "pg-driver": [],
    "left-pad-ng": [],
}

def admit(artifacts):
    admitted = 0
    for a in artifacts:
        if a["signed_by"] is None:
            print(f"{a['name']} -> DENY (unsigned)")
        elif a["signed_by"] not in TRUSTED_SIGNERS:
            print(f"{a['name']} -> DENY (untrusted signer {a['signed_by']})")
        elif not a["sbom"]:
            print(f"{a['name']} -> DENY (no sbom attestation)")
        elif a["criticals"]:
            print(f"{a['name']} -> DENY (criticals={len(a['criticals'])}: {', '.join(a['criticals'])})")
        else:
            admitted += 1
            print(f"{a['name']} -> ALLOW (signed={a['signed_by']}, sbom=yes, criticals=0)")
    print(f"admitted: {admitted}/{len(artifacts)}")

def dep_path(tree, target):
    def dfs(node, path):
        if node == target:
            return path
        for child in tree.get(node, []):
            found = dfs(child, path + [child])
            if found:
                return found
        return None
    path = dfs("app", ["app"])
    depth = len(path) - 1
    print(f"dep path to {target}: {' -> '.join(path)} (depth {depth}, transitive)")

admit(ARTIFACTS)
dep_path(DEPS, "left-pad-ng")

