CONTROLS = ["rollout-strategy", "rollback", "health-probes", "telemetry-slo", "runbook"]

SERVICES = {
    "orders-api": {
        "rollout-strategy": (True, True, "canary transcript 2026-07-02"),
        "rollback": (True, True, "undo drill, 94s to healthy"),
        "health-probes": (True, True, "drain observed in endpoints diff"),
        "telemetry-slo": (True, False, "alert configured, never test-fired"),
        "runbook": (True, True, "executed as drill, steps 3+6 corrected"),
    },
    "batch-etl": {
        "rollout-strategy": (True, True, "rolling update transcript"),
        "rollback": (True, False, "undo documented, never drilled"),
        "health-probes": (False, False, ""),
        "telemetry-slo": (True, True, "synthetic burn paged on-call"),
        "runbook": (False, False, ""),
    },
}

def score_prr(services):
    ready_count = 0
    for name, controls in services.items():
        print(f"{name} PRR:")
        unproven = []
        for c in CONTROLS:
            present, fired, note = controls[c]
            if present and fired:
                print(f"  {c}: PASS ({note})")
            elif present:
                print(f"  {c}: FAIL (configured, never fired)")
                unproven.append(c)
            else:
                print(f"  {c}: FAIL (missing)")
                unproven.append(c)
        if not unproven:
            ready_count += 1
            print("verdict: READY (5/5 controls proven)")
        else:
            print(f"verdict: BLOCKED ({len(unproven)} of 5 controls unproven: {', '.join(unproven)})")
    print(f"fleet: {ready_count}/{len(services)} services production-ready")

score_prr(SERVICES)
